const setting = {
    fastify: {}
};

function getSetting() {
    return setting;
}

function setSetting(fastify) {
    if (typeof fastify !== 'object' || fastify === null) {
        throw new Error('Invalid fastify object provided');
    }

    if (Object.keys(setting.fastify).length === 0) {
        setting.fastify = fastify;
        return true;
    }

    return false;
}

export {
    getSetting,
    setSetting
}
